module average_operations (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] pattern,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] ITER = 2'd1;\n    localparam [1:0] COMPUTE = 2'd2;\n    localparam [1:0] DONE_STATE = 2'd3;\n    reg [1:0] state;\n    reg [1:0] next_state;\n\n    // ROM declaration\n    reg [7:0] dist_rom [0:15];\n    initial begin\n        dist_rom[0]  = 8'd0; \n        dist_rom[1]  = 8'd1;\n        dist_rom[2]  = 8'd3;\n        dist_rom[3]  = 8'd2;\n        dist_rom[4]  = 8'd5;\n        dist_rom[5]  = 8'd4;\n        dist_rom[6]  = 8'd6;\n        dist_rom[7]  = 8'd3;\n        dist_rom[8]  = 8'd7;\n        dist_rom[9]  = 8'd6;\n        dist_rom[10] = 8'd8;\n        dist_rom[11] = 8'd5;\n        dist_rom[12] = 8'd10;\n        dist_rom[13] = 8'd7;\n        dist_rom[14] = 8'd9;\n        dist_rom[15] = 8'd4;\n    end\n\n    // Internal registers\n    reg [3:0] i;\n    reg [15:0] sum;\n    reg [2:0] q_count;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    // Match detection\n    reg match;\n    integer j;\n    always @(*) begin\n        match = 1'b1;\n        for (j = 0; j < 4; j = j + 1) begin\n            case (pattern[2*j +: 2])\n                2'b00: if (i[j] != 1'b0) match = 1'b0;\n                2'b01: if (i[j] != 1'b1) match = 1'b0;\n                default: ;\n            endcase\n        end\n    end\n\n    // '?' counter\n    always @(*) begin\n        q_count = 3'd0;\n        for (j = 0; j < 4; j = j + 1) begin\n            if (pattern[2*j +: 2] == 2'b10) q_count = q_count + 3'd1;\n        end\n    end\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            i <= 4'd0;\n            sum <= 16'd0;\n            result <= 32'd0;\n            done <= 1'b0;\n            cycle_count <= 8'd0;\n        end else begin\n            cycle_count <= (state == ITER) ? cycle_count + 1'd1 : 8'd0;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    sum <= 16'd0;\n                    done <= 1'b0;\n                    if (start) begin\n                        i <= 4'd0;\n                        next_state <= ITER;\n                    end\n                end\n\n                ITER: begin\n                    if (match) sum <= sum + dist_rom[i];\n                    if (i == 4'd15) begin\n                        next_state <= COMPUTE;\n                    end else begin\n                        i <= i + 1'd1;\n                    end\n                    if (cycle_count >= MAX_CYCLES) next_state <= COMPUTE;\n                end\n\n                COMPUTE: begin\n                    case (q_count)\n                        3'd0: result <= sum << 16;\n                        3'd1: result <= sum << 15;\n                        3'd2: result <= sum << 14;\n                        3'd3: result <= sum << 13;\n                        3'd4: result <= sum << 12;\n                        default: result <= 32'd0;\n                    endcase\n                    done <= 1'b1;\n                    next_state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b0;\n                    next_state <= IDLE;\n                end\n\n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule